-- Fixtures isoladas mínimas. Não executar em projeto Supabase real.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth TO anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION auth.uid() TO anon,authenticated,service_role;
CREATE TABLE public.salons(id uuid PRIMARY KEY,owner_id uuid,name text,working_hours jsonb,working_days integer[] DEFAULT ARRAY[0,1,2,3,4,5,6],opening_time time DEFAULT '09:00',closing_time time DEFAULT '18:00',lunch_break_config jsonb);
CREATE TABLE public.services(id uuid PRIMARY KEY,salon_id uuid,name text,price numeric,duration_minutes integer,is_active boolean DEFAULT true);
CREATE TABLE public.professionals(id uuid PRIMARY KEY,salon_id uuid,name text,is_active boolean DEFAULT true,working_days integer[] DEFAULT ARRAY[0,1,2,3,4,5,6]);
CREATE TABLE public.user_roles(id uuid DEFAULT gen_random_uuid(),user_id uuid,role text,salon_id uuid,UNIQUE(user_id,role,salon_id));
CREATE FUNCTION public.user_belongs_to_salon(s uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM public.salons WHERE id=s AND owner_id=auth.uid()) $$;
CREATE TABLE public.appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),salon_id uuid,service_id uuid,professional_id uuid,client_id uuid,client_name text,client_phone text,date date,start_time time,end_time time,price numeric,final_price numeric,status text,updated_at timestamptz DEFAULT now());
CREATE TABLE public.clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),salon_id uuid,name text,phone text,email text,created_at timestamptz DEFAULT now());
CREATE TABLE public.whatsapp_instances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),salon_id uuid NOT NULL UNIQUE REFERENCES salons(id),instance_name text,status text,instance_token text,qrcode text,api_url text,webhook_url text,phone_number text,updated_at timestamptz);
CREATE TABLE public.broadcasts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),salon_id uuid,message text,total_recipients integer,sent_count integer,failed_count integer,status varchar CHECK(status IN('pending','processing','completed','stopped','failed')),error_message text,created_at timestamptz DEFAULT now(),completed_at timestamptz,progress_percent integer,last_activity_at timestamptz);
CREATE TABLE public.broadcast_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),broadcast_id uuid,salon_id uuid,recipient_phone text,recipient_name text,message text,status text CHECK(status IN('pending','processing','sent','failed')),attempts integer DEFAULT 0,max_attempts integer DEFAULT 3,error_message text,scheduled_for timestamptz DEFAULT now(),processed_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.broadcast_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),broadcast_id uuid,salon_id uuid,recipient_phone text,recipient_name text,status varchar CHECK(status IN('pending','sent','failed','delivered','read')),error_message text,whatsapp_message_id text,sent_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE public.chatbot_settings(id uuid DEFAULT gen_random_uuid(),salon_id uuid UNIQUE,enabled boolean,api_key text);
CREATE TABLE public.chatbot_conversations(id uuid DEFAULT gen_random_uuid(),salon_id uuid,client_phone text,client_name text,direction text,content text,whatsapp_message_id text,ai_response boolean,status text);
CREATE TABLE public.broadcast_templates(id uuid,salon_id uuid,name text,content text);
ALTER TABLE public.broadcast_queue ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.broadcast_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service role can manage broadcast queue" ON public.broadcast_queue FOR ALL USING(true) WITH CHECK(true);
CREATE POLICY "Salons can manage their own templates" ON public.broadcast_templates FOR ALL USING(true);
CREATE TABLE public.scheduled_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),salon_id uuid,content_type text,text_content text,media_url text,media_filename text,scheduled_at timestamptz,recurrence_type text DEFAULT 'once',recurrence_days integer[],recurrence_end_date date,status text DEFAULT 'scheduled',posted_at timestamptz,error_message text,whatsapp_status_id text,created_by uuid,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid,bucket_id text,name text);
CREATE FUNCTION storage.foldername(text) RETURNS text[] LANGUAGE sql AS $$ SELECT string_to_array($1,'/') $$;
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
GRANT USAGE ON SCHEMA public TO anon,authenticated,service_role;
GRANT SELECT ON salons,user_roles TO authenticated;
GRANT ALL ON broadcast_queue,broadcast_templates TO anon,authenticated,service_role;
